	this.shape_8.graphics.f().s("#1B1B1D").p("AArA6IgpgiIg0A/IgcgYIA2g/IgkgdIAXgcIAkAfIA0g/IAcAXIg1A/IAoAhgABDhPQghgbgqADQgrAEgcAhQgbAhADAqQAEArAhAbQAhAcAqgDQAqgEAcghQAcghgEgqQgDgrghgcg");
	this.shape_8.setTransform(-82.7459,30.0844,1.0243,1.0243,-10.9067);

	this.shape_9 = new cjs.Shape();
	this.shape_9.graphics.f("#FFFFFF").s().p("AhCBPQghgbgEgrQgDgqAbghQAcghArgEQAqgDAhAbQAhAcADArQAEAqgcAhQgcAhgqAEIgJAAQglAAgdgZgAg8gdIAkAdIg2A/IAcAYIA0g/IApAiIAXgcIgoghIA1g/IgcgXIg0A/Igkgfg");
	this.shape_9.setTransform(-82.7459,30.0844,1.0243,1.0243,-10.9067);

	this.shape_10 = new cjs.Shape();
	this.shape_10.graphics.f().s("#1B1B1D").p("ACEAlQAqgxgGhAQgFhBgygqQgygqg/AGQhBAFgqAyQgqAyAFBAQAGBAAyAqQALAJALAHQgxA6gyA1IAqAkQA4g7A6hFQAmAGAmgOQAmgOAbggg");
	this.shape_10.setTransform(24.3114,57.0399,1,1,-10.9061);

	this.shape_11 = new cjs.Shape();
	this.shape_11.graphics.f("#ED1B6D").s().p("AinC4QAzg1Awg6QgLgHgLgJQgygqgFhAQgGhAAqgyQAqgyBBgFQBAgGAxAqQAyAqAGBBQAFBAgqAxQgaAggnAOQglAOgngGQg5BFg5A7g");
