	this.ikNode_40.name = "ikNode_40";
	this.ikNode_40.setTransform(21.55,44.45,1.1529,1.0584,-19.2022,0,0,34.5,39.4);

	this.platina = new lib.platina();
	this.platina.name = "platina";
	this.platina.setTransform(-29.3,35.95,1,1,-45);

