	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.governor},{t:this.platina},{t:this.ikNode_40},{t:this.shape_11},{t:this.shape_10},{t:this.shape_9},{t:this.shape_8},{t:this.shape_7},{t:this.shape_6},{t:this.shape_5},{t:this.shape_4},{t:this.shape_3},{t:this.shape_2},{t:this.shape_1},{t:this.shape},{t:this.inti},{t:this.pusatPlatina},{t:this.api},{t:this.tanda},{t:this.titik3},{t:this.titik4},{t:this.titik5},{t:this.titik6},{t:this.titik7},{t:this.titik8},{t:this.titik9},{t:this.titik10},{t:this.titik2},{t:this.titik1}]}).wait(1));

